def validate(ref_time, ref_freqs, est_time, est_freqs):
    util.validate_events(ref_time, max_time=MAX_TIME)
    util.validate_events(est_time, max_time=MAX_TIME)
    if ref_time.size == 0:
        warnings.warn("Reference times are empty.")
    if ref_time.ndim != 1:
        raise ValueError("Reference times have invalid dimension")
    if len(ref_freqs) == 0:
        warnings.warn("Reference frequencies are empty.")
    if est_time.size == 0:
        warnings.warn("Estimated times are empty.")
    if est_time.ndim != 1:
        raise ValueError("Estimated times have invalid dimension")
    if len(est_freqs) == 0:
        warnings.warn("Estimated frequencies are empty.")
    if ref_time.size != len(ref_freqs):
        raise ValueError("Reference times and frequencies have unequal lengths. Verify that the number of time stamps matches the number of frequency arrays provided.")
    if est_time.size != len(est_freqs):
        raise ValueError("Estimate times and frequencies have unequal lengths. Verify that the number of time stamps matches the number of frequency arrays provided.")
    for freq in ref_freqs:
        util.validate_frequencies(freq, max_freq=MAX_FREQ, min_freq=MIN_FREQ, allow_negatives=False)
    for freq in est_freqs:
        util.validate_frequencies(freq, max_freq=MAX_FREQ, min_freq=MIN_FREQ, allow_negatives=False)

def validate(ref_intervals, ref_pitches, est_intervals, est_pitches):
    validate_intervals(ref_intervals, est_intervals)
    if not ref_intervals.shape[0] == ref_pitches.shape[0]:
        raise ValueError("Reference intervals and pitches have different lengths. Ensure the number of rows in the interval array matches the number of elements in the pitch array.")
    if not est_intervals.shape[0] == est_pitches.shape[0]:
        raise ValueError("Estimated intervals and pitches have different lengths. Ensure the number of rows in the interval array matches the number of elements in the pitch array.")
    if ref_pitches.size > 0 and np.min(ref_pitches) <= 0:
        raise ValueError("Reference contains at least one non-positive pitch value")
    if est_pitches.size > 0 and np.min(est_pitches) <= 0:
        raise ValueError("Estimate contains at least one non-positive pitch value")
